// Build a set of every confirmationId already in use
const usedIds = new Set(items.map(i => i.json.confirmationId).filter(Boolean));

function generateId() {
  const digits = Math.floor(1000 + Math.random() * 9000); // always 4 digits
  return 'MC-' + digits;
}

let newId = generateId();
let attempts = 0;
while (usedIds.has(newId) && attempts < 50) {
  newId = generateId();
  attempts++;
}

const booking = $('New Booking Form Response').first().json;
booking.confirmationId = newId;
booking.status = 'Pending';
return [{ json: booking }];

